type Invoice = { id: string; number: string; client: string; amount: number; currency: string; status: 'Paid' | 'Due soon' | 'Overdue' | 'Draft'; dueDate: string };
type ActivityItem = { id: string; actor: string; action: string; target: string; time: string; type: 'invoice' | 'project' | 'customer' | 'system'; initials: string };

